let S = 100;

function setup() {
	createCanvas(600, 600);
	background("grey")
	// rectMode(CENTER)
	frameRate(15)
	noStroke()
}

function draw() {
	for (let y = 0; y < height; y += S) {
		for (let x = 0; x < width; x += S) {
			const clr = 128 + 128 * noise(x * 0.323, y * 0.1231, frameCount * 0.012);
			fill(128, 160, clr)
			rect(x, y, S)
		}		
	}
}
